create table if not exists public.audit_events (id uuid primary key default gen_random_uuid(), actor_user_id uuid references auth.users(id) on delete set null, project_id text, event_type text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists audit_events_project_created_at_idx on public.audit_events (project_id, created_at desc);
create index if not exists audit_events_actor_created_at_idx on public.audit_events (actor_user_id, created_at desc);
alter table public.audit_events enable row level security;
alter table public.audit_events force row level security;
drop policy if exists "Users can read their audit events" on public.audit_events;
create policy "Users can read their audit events" on public.audit_events for select to authenticated using (actor_user_id = (select auth.uid()));
revoke insert, update, delete on public.audit_events from authenticated, anon;
create or replace function public.write_audit_event(p_event_type text,p_entity_type text,p_entity_id text,p_project_id text,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path = public as $$ begin insert into public.audit_events(actor_user_id,project_id,event_type,entity_type,entity_id,metadata) values ((select auth.uid()),p_project_id,p_event_type,p_entity_type,p_entity_id,coalesce(p_metadata,'{}'::jsonb)); end; $$;
revoke all on function public.write_audit_event(text,text,text,text,jsonb) from public, anon, authenticated;
create or replace function public.audit_projects() returns trigger language plpgsql security definer set search_path = public as $$ begin perform public.write_audit_event(case tg_op when 'INSERT' then 'project.created' when 'UPDATE' then 'project.updated' else 'project.deleted' end,'project',coalesce(new.id,old.id),coalesce(new.id,old.id),jsonb_build_object('operation',tg_op)); return coalesce(new,old); end; $$;
create or replace function public.audit_documents() returns trigger language plpgsql security definer set search_path = public as $$ begin perform public.write_audit_event(case when tg_op='INSERT' then 'document.created' when tg_op='UPDATE' and new.status is distinct from old.status then 'document.status_changed' when tg_op='UPDATE' then 'document.updated' else 'document.deleted' end,'document',coalesce(new.id,old.id),coalesce(new.project_id,old.project_id),jsonb_build_object('operation',tg_op,'status',coalesce(new.status,old.status),'version',coalesce(new.version,old.version))); return coalesce(new,old); end; $$;
create or replace function public.audit_ai_tasks() returns trigger language plpgsql security definer set search_path = public as $$ begin if tg_op='INSERT' or new.status is distinct from old.status then perform public.write_audit_event(case when tg_op='INSERT' then 'ai_task.created' else 'ai_task.status_changed' end,'ai_task',coalesce(new.id,old.id),coalesce(new.project_id,old.project_id),jsonb_build_object('operation',tg_op,'status',coalesce(new.status,old.status),'attempts',coalesce(new.attempts,old.attempts))); end if; return coalesce(new,old); end; $$;
drop trigger if exists projects_audit_trigger on public.projects;
create trigger projects_audit_trigger after insert or update or delete on public.projects for each row execute function public.audit_projects();
drop trigger if exists documents_audit_trigger on public.documents;
create trigger documents_audit_trigger after insert or update or delete on public.documents for each row execute function public.audit_documents();
drop trigger if exists ai_tasks_audit_trigger on public.ai_tasks;
create trigger ai_tasks_audit_trigger after insert or update or delete on public.ai_tasks for each row execute function public.audit_ai_tasks();